"use client";

import React, { useEffect, useMemo, useState, useCallback } from "react";
import { ShieldCheck, SlidersHorizontal, X, CheckCircle2 } from "lucide-react";
import { useTranslations, useLocale } from "next-intl";
import { useConsent } from "./ConsentProvider";
import { cn } from "@/lib/utils";

interface CategoryCardProps {
  title: string;
  description: string;
  enabled: boolean;
  onToggle?: () => void;
  locked?: boolean;
}

const CategoryCard = ({ title, description, enabled, onToggle, locked }: CategoryCardProps) => (
  <div
    className={cn(
      "border-2 border-neo-border bg-neo-surface p-3 shadow-[3px_3px_0px_0px_var(--neo-border)]"
    )}
  >
    <div className="flex items-center justify-between gap-2 mb-1">
      <div className="flex items-center gap-2">
        <div className="w-2 h-2 rounded-full bg-neo-accent" />
        <h4 className="text-xs font-black uppercase tracking-tight">{title}</h4>
      </div>
      <button
        disabled={locked}
        onClick={onToggle}
        className={cn(
          "px-2 py-0.5 font-mono text-[9px] uppercase tracking-[0.15em] border-2 border-neo-border",
          enabled
            ? "bg-neo-accent text-neo-text shadow-[2px_2px_0px_0px_var(--neo-border)]"
            : "bg-neo-surface text-neo-text/70",
          locked && "opacity-60 cursor-not-allowed"
        )}
      >
        {locked ? "On" : enabled ? "On" : "Off"}
      </button>
    </div>
    <p className="text-xs text-neo-text/80 leading-relaxed">{description}</p>
  </div>
);

export const NeoCookieConsent = () => {
  const t = useTranslations("consent");
  const locale = useLocale();
  const { state, isReady, isManagerOpen, closeManager, acceptAll, rejectAll, setCategory } =
    useConsent();
  const [showDetails, setShowDetails] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  // Animation d'entrée
  useEffect(() => {
    if (isManagerOpen) {
      setShowDetails(false);
      // Petit délai pour déclencher l'animation
      const timer = setTimeout(() => setIsVisible(true), 50);
      return () => clearTimeout(timer);
    } else {
      setIsVisible(false);
    }
  }, [isManagerOpen]);

  // Acceptation au scroll
  useEffect(() => {
    if (!isManagerOpen || !isReady) return;

    const handleScroll = () => {
      // Accepter les cookies essentiels uniquement au scroll (comportement "continuer sans accepter")
      acceptAll();
    };

    // Ajouter l'écouteur avec un petit délai pour éviter les déclenchements accidentels
    const timer = setTimeout(() => {
      window.addEventListener("scroll", handleScroll, { once: true, passive: true });
    }, 500);

    return () => {
      clearTimeout(timer);
      window.removeEventListener("scroll", handleScroll);
    };
  }, [isManagerOpen, isReady, acceptAll]);

  const categories = useMemo(
    () => [
      {
        key: "essential",
        title: t("categories.essential.title"),
        description: t("categories.essential.description"),
        enabled: true,
        locked: true,
      },
      {
        key: "media",
        title: t("categories.media.title"),
        description: t("categories.media.description"),
        enabled: state.media,
      },
      {
        key: "analytics",
        title: t("categories.analytics.title"),
        description: t("categories.analytics.description"),
        enabled: state.analytics,
      },
    ],
    [state.media, state.analytics, t]
  );

  const handleClose = useCallback(() => {
    setIsVisible(false);
    // Attendre la fin de l'animation avant de fermer
    setTimeout(() => {
      setShowDetails(false);
      closeManager();
    }, 300);
  }, [closeManager]);

  if (!isReady || !isManagerOpen) return null;

  return (
    <div
      className={cn(
        "fixed bottom-0 left-0 right-0 z-50 transition-transform duration-300 ease-out",
        isVisible ? "translate-y-0" : "translate-y-full"
      )}
    >
      <div className="w-full border-t-4 border-neo-border bg-neo-text text-neo-text-inverse shadow-[0_-8px_30px_rgba(0,0,0,0.3)]">
        {/* Contenu principal du bandeau */}
        <div className="relative px-4 py-4 md:px-8 md:py-5">
          {/* Bouton fermer */}
          <button
            onClick={handleClose}
            aria-label={t("actions.close")}
            className="absolute top-3 right-3 md:top-4 md:right-4 p-2 border-2 border-neo-border bg-neo-text text-neo-text-inverse shadow-[3px_3px_0px_0px_var(--neo-accent)] hover:bg-neo-accent hover:text-neo-text transition-colors"
          >
            <X className="w-4 h-4" />
          </button>

          <div className="max-w-7xl mx-auto">
            {/* Layout principal : flex sur desktop, stack sur mobile */}
            <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 pr-12 md:pr-16">
              {/* Partie gauche : badge + titre + description */}
              <div className="flex flex-col sm:flex-row sm:items-center gap-3 lg:gap-6 flex-1">
                <div className="flex items-center gap-3">
                  <div className="inline-flex items-center gap-2 bg-neo-accent text-neo-text px-3 py-1 font-mono text-[10px] uppercase tracking-[0.2em] shadow-[3px_3px_0px_0px_var(--neo-border)] shrink-0">
                    <ShieldCheck className="w-4 h-4" />
                    {t("badge")}
                  </div>
                  <h3 className="text-lg md:text-xl font-black uppercase tracking-tight text-white whitespace-nowrap">
                    {t("title")}
                  </h3>
                </div>
                <p className="text-sm text-neo-text-inverse/80 leading-relaxed max-w-xl">
                  {t("description")}
                </p>
              </div>

              {/* Partie droite : boutons d'action */}
              <div className="flex flex-wrap items-center gap-2 md:gap-3 shrink-0">
                <button
                  onClick={acceptAll}
                  className="px-4 py-2 bg-neo-accent text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-border)] transition-all"
                >
                  {t("actions.acceptAll")}
                </button>
                <button
                  onClick={rejectAll}
                  className="px-4 py-2 bg-neo-text-inverse text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-border)] transition-all"
                >
                  {t("actions.rejectAll")}
                </button>
                <button
                  onClick={() => setShowDetails((prev) => !prev)}
                  className="px-4 py-2 bg-neo-text text-neo-text-inverse font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-accent)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-accent)] transition-all inline-flex items-center gap-2"
                >
                  <SlidersHorizontal className="w-4 h-4" />
                  {showDetails ? t("actions.close") : t("actions.customize")}
                </button>
              </div>
            </div>

            {/* Ligne info */}
            <div className="flex items-center gap-2 mt-3 text-[10px] uppercase font-mono tracking-[0.14em] text-neo-text-inverse/60">
              <CheckCircle2 className="w-3 h-3" />
              {t("lastUpdatedLabel", { date: t("lastUpdated") })}
              <span className="opacity-50">|</span>
              <span>{locale.toUpperCase()}</span>
              <span className="opacity-50">|</span>
              <span className="text-neo-accent">{t("scrollToAccept") || "Scroll = Accept"}</span>
            </div>
          </div>
        </div>

        {/* Panel de détails (catégories) */}
        {showDetails && (
          <div className="border-t-2 border-neo-border bg-neo-surface text-neo-text">
            <div className="max-w-7xl mx-auto px-4 py-4 md:px-8">
              <h4 className="font-mono text-[10px] uppercase tracking-[0.2em] text-neo-accent mb-3">
                {t("categoriesTitle")}
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {categories.map((cat) => (
                  <CategoryCard
                    key={cat.key}
                    title={cat.title}
                    description={cat.description}
                    enabled={cat.enabled}
                    locked={cat.locked}
                    onToggle={
                      cat.locked
                        ? undefined
                        : () => setCategory(cat.key as "media" | "analytics", !cat.enabled)
                    }
                  />
                ))}
              </div>
              <div className="flex flex-wrap gap-2 mt-4">
                <button
                  onClick={() => {
                    closeManager();
                    setShowDetails(false);
                  }}
                  className="px-4 py-2 bg-neo-accent text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 transition-transform"
                >
                  {t("actions.save")}
                </button>
                <button
                  onClick={() => setShowDetails(false)}
                  className="px-4 py-2 bg-neo-surface text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 transition-transform"
                >
                  {t("actions.close")}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

