     1→"use client";
     2→
     3→import React, { useEffect, useMemo, useState, useCallback } from "react";
     4→import { ShieldCheck, SlidersHorizontal, X, CheckCircle2 } from "lucide-react";
     5→import { useTranslations, useLocale } from "next-intl";
     6→import { useConsent } from "./ConsentProvider";
     7→import { cn } from "@/lib/utils";
     8→
     9→interface CategoryCardProps {
    10→  title: string;
    11→  description: string;
    12→  enabled: boolean;
    13→  onToggle?: () => void;
    14→  locked?: boolean;
    15→}
    16→
    17→const CategoryCard = ({ title, description, enabled, onToggle, locked }: CategoryCardProps) => (
    18→  <div
    19→    className={cn(
    20→      "border-2 border-neo-border bg-neo-surface p-3 shadow-[3px_3px_0px_0px_var(--neo-border)]"
    21→    )}
    22→  >
    23→    <div className="flex items-center justify-between gap-2 mb-1">
    24→      <div className="flex items-center gap-2">
    25→        <div className="w-2 h-2 rounded-full bg-neo-accent" />
    26→        <h4 className="text-xs font-black uppercase tracking-tight">{title}</h4>
    27→      </div>
    28→      <button
    29→        disabled={locked}
    30→        onClick={onToggle}
    31→        className={cn(
    32→          "px-2 py-0.5 font-mono text-[9px] uppercase tracking-[0.15em] border-2 border-neo-border",
    33→          enabled
    34→            ? "bg-neo-accent text-neo-text shadow-[2px_2px_0px_0px_var(--neo-border)]"
    35→            : "bg-neo-surface text-neo-text/70",
    36→          locked && "opacity-60 cursor-not-allowed"
    37→        )}
    38→      >
    39→        {locked ? "On" : enabled ? "On" : "Off"}
    40→      </button>
    41→    </div>
    42→    <p className="text-xs text-neo-text/80 leading-relaxed">{description}</p>
    43→  </div>
    44→);
    45→
    46→export const NeoCookieConsent = () => {
    47→  const t = useTranslations("consent");
    48→  const locale = useLocale();
    49→  const { state, isReady, isManagerOpen, closeManager, acceptAll, rejectAll, setCategory } =
    50→    useConsent();
    51→  const [showDetails, setShowDetails] = useState(false);
    52→  const [isVisible, setIsVisible] = useState(false);
    53→
    54→  // Animation d'entrée
    55→  useEffect(() => {
    56→    if (isManagerOpen) {
    57→      setShowDetails(false);
    58→      // Petit délai pour déclencher l'animation
    59→      const timer = setTimeout(() => setIsVisible(true), 50);
    60→      return () => clearTimeout(timer);
    61→    } else {
    62→      setIsVisible(false);
    63→    }
    64→  }, [isManagerOpen]);
    65→
    66→  // Acceptation au scroll
    67→  useEffect(() => {
    68→    if (!isManagerOpen || !isReady) return;
    69→
    70→    const handleScroll = () => {
    71→      // Accepter les cookies essentiels uniquement au scroll (comportement "continuer sans accepter")
    72→      acceptAll();
    73→    };
    74→
    75→    // Ajouter l'écouteur avec un petit délai pour éviter les déclenchements accidentels
    76→    const timer = setTimeout(() => {
    77→      window.addEventListener("scroll", handleScroll, { once: true, passive: true });
    78→    }, 500);
    79→
    80→    return () => {
    81→      clearTimeout(timer);
    82→      window.removeEventListener("scroll", handleScroll);
    83→    };
    84→  }, [isManagerOpen, isReady, acceptAll]);
    85→
    86→  const categories = useMemo(
    87→    () => [
    88→      {
    89→        key: "essential",
    90→        title: t("categories.essential.title"),
    91→        description: t("categories.essential.description"),
    92→        enabled: true,
    93→        locked: true,
    94→      },
    95→      {
    96→        key: "media",
    97→        title: t("categories.media.title"),
    98→        description: t("categories.media.description"),
    99→        enabled: state.media,
   100→      },
   101→      {
   102→        key: "analytics",
   103→        title: t("categories.analytics.title"),
   104→        description: t("categories.analytics.description"),
   105→        enabled: state.analytics,
   106→      },
   107→    ],
   108→    [state.media, state.analytics, t]
   109→  );
   110→
   111→  const handleClose = useCallback(() => {
   112→    setIsVisible(false);
   113→    // Attendre la fin de l'animation avant de fermer
   114→    setTimeout(() => {
   115→      setShowDetails(false);
   116→      closeManager();
   117→    }, 300);
   118→  }, [closeManager]);
   119→
   120→  if (!isReady || !isManagerOpen) return null;
   121→
   122→  return (
   123→    <div
   124→      className={cn(
   125→        "fixed bottom-0 left-0 right-0 z-50 transition-transform duration-300 ease-out",
   126→        isVisible ? "translate-y-0" : "translate-y-full"
   127→      )}
   128→    >
   129→      <div className="w-full border-t-4 border-neo-border bg-neo-text text-neo-text-inverse shadow-[0_-8px_30px_rgba(0,0,0,0.3)]">
   130→        {/* Contenu principal du bandeau */}
   131→        <div className="relative px-4 py-4 md:px-8 md:py-5">
   132→          {/* Bouton fermer */}
   133→          <button
   134→            onClick={handleClose}
   135→            aria-label={t("actions.close")}
   136→            className="absolute top-3 right-3 md:top-4 md:right-4 p-2 border-2 border-neo-border bg-neo-text text-neo-text-inverse shadow-[3px_3px_0px_0px_var(--neo-accent)] hover:bg-neo-accent hover:text-neo-text transition-colors"
   137→          >
   138→            <X className="w-4 h-4" />
   139→          </button>
   140→
   141→          <div className="max-w-7xl mx-auto">
   142→            {/* Layout principal : flex sur desktop, stack sur mobile */}
   143→            <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 pr-12 md:pr-16">
   144→              {/* Partie gauche : badge + titre + description */}
   145→              <div className="flex flex-col sm:flex-row sm:items-center gap-3 lg:gap-6 flex-1">
   146→                <div className="flex items-center gap-3">
   147→                  <div className="inline-flex items-center gap-2 bg-neo-accent text-neo-text px-3 py-1 font-mono text-[10px] uppercase tracking-[0.2em] shadow-[3px_3px_0px_0px_var(--neo-border)] shrink-0">
   148→                    <ShieldCheck className="w-4 h-4" />
   149→                    {t("badge")}
   150→                  </div>
   151→                  <h3 className="text-lg md:text-xl font-black uppercase tracking-tight text-white whitespace-nowrap">
   152→                    {t("title")}
   153→                  </h3>
   154→                </div>
   155→                <p className="text-sm text-neo-text-inverse/80 leading-relaxed max-w-xl">
   156→                  {t("description")}
   157→                </p>
   158→              </div>
   159→
   160→              {/* Partie droite : boutons d'action */}
   161→              <div className="flex flex-wrap items-center gap-2 md:gap-3 shrink-0">
   162→                <button
   163→                  onClick={acceptAll}
   164→                  className="px-4 py-2 bg-neo-accent text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-border)] transition-all"
   165→                >
   166→                  {t("actions.acceptAll")}
   167→                </button>
   168→                <button
   169→                  onClick={rejectAll}
   170→                  className="px-4 py-2 bg-neo-text-inverse text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-border)] transition-all"
   171→                >
   172→                  {t("actions.rejectAll")}
   173→                </button>
   174→                <button
   175→                  onClick={() => setShowDetails((prev) => !prev)}
   176→                  className="px-4 py-2 bg-neo-text text-neo-text-inverse font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-accent)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-accent)] transition-all inline-flex items-center gap-2"
   177→                >
   178→                  <SlidersHorizontal className="w-4 h-4" />
   179→                  {showDetails ? t("actions.close") : t("actions.customize")}
   180→                </button>
   181→              </div>
   182→            </div>
   183→
   184→            {/* Ligne info */}
   185→            <div className="flex items-center gap-2 mt-3 text-[10px] uppercase font-mono tracking-[0.14em] text-neo-text-inverse/60">
   186→              <CheckCircle2 className="w-3 h-3" />
   187→              {t("lastUpdatedLabel", { date: t("lastUpdated") })}
   188→              <span className="opacity-50">|</span>
   189→              <span>{locale.toUpperCase()}</span>
   190→              <span className="opacity-50">|</span>
   191→              <span className="text-neo-accent">{t("scrollToAccept") || "Scroll = Accept"}</span>
   192→            </div>
   193→          </div>
   194→        </div>
   195→
   196→        {/* Panel de détails (catégories) */}
   197→        {showDetails && (
   198→          <div className="border-t-2 border-neo-border bg-neo-surface text-neo-text">
   199→            <div className="max-w-7xl mx-auto px-4 py-4 md:px-8">
   200→              <h4 className="font-mono text-[10px] uppercase tracking-[0.2em] text-neo-accent mb-3">
   201→                {t("categoriesTitle")}
   202→              </h4>
   203→              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
   204→                {categories.map((cat) => (
   205→                  <CategoryCard
   206→                    key={cat.key}
   207→                    title={cat.title}
   208→                    description={cat.description}
   209→                    enabled={cat.enabled}
   210→                    locked={cat.locked}
   211→                    onToggle={
   212→                      cat.locked
   213→                        ? undefined
   214→                        : () => setCategory(cat.key as "media" | "analytics", !cat.enabled)
   215→                    }
   216→                  />
   217→                ))}
   218→              </div>
   219→              <div className="flex flex-wrap gap-2 mt-4">
   220→                <button
   221→                  onClick={() => {
   222→                    closeManager();
   223→                    setShowDetails(false);
   224→                  }}
