              <div className="flex flex-col gap-2 flex-1">
                <div className="inline-flex items-center gap-2 bg-neo-accent text-neo-text px-3 py-1 font-mono text-[10px] uppercase tracking-[0.2em] shadow-[3px_3px_0px_0px_var(--neo-border)] w-fit">
                  <ShieldCheck className="w-4 h-4" />
                  {t("badge")}
                </div>
                <h3 className="text-lg md:text-xl font-black uppercase tracking-tight text-white">
                  {t("title")}
                </h3>
                <p className="text-sm text-neo-text-inverse/80 leading-relaxed max-w-xl">
                  {t("description")}
                </p>
                {/* Ligne info */}
                <div className="flex items-center gap-2 mt-1 text-[10px] uppercase font-mono tracking-[0.14em] text-neo-text-inverse/60">
                  <CheckCircle2 className="w-3 h-3" />
                  {t("lastUpdatedLabel", { date: t("lastUpdated") })}
                  <span className="opacity-50">|</span>
                  <span>{locale.toUpperCase()}</span>
                </div>
              </div>

              {/* Partie droite : boutons d'action empilés verticalement */}
              <div className="flex flex-col gap-2 shrink-0">
                <button
                  onClick={acceptAll}
                  className="px-4 py-2 bg-neo-accent text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-border)] transition-all"
                >
                  {t("actions.acceptAll")}
                </button>
                <button
                  onClick={rejectAll}
                  className="px-4 py-2 bg-neo-text-inverse text-neo-text font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-border)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-border)] transition-all"
                >
                  {t("actions.rejectAll")}
                </button>
                <button
                  onClick={() => setShowDetails((prev) => !prev)}
                  className="px-4 py-2 bg-neo-text text-neo-text-inverse font-mono text-xs uppercase font-bold border-2 border-neo-border shadow-[4px_4px_0px_0px_var(--neo-accent)] hover:-translate-y-0.5 hover:shadow-[6px_6px_0px_0px_var(--neo-accent)] transition-all inline-flex items-center justify-center gap-2"
                >
                  <SlidersHorizontal className="w-4 h-4" />
                  {showDetails ? t("actions.close") : t("actions.customize")}
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Panel de détails (catégories) */}
        {showDetails && (
          <div className="border-t-2 border-neo-border bg-neo-surface text-neo-text">
            <div className="max-w-7xl mx-auto px-4 py-4 md:px-8">
